import re

def slugify(title):
    return re.sub(r'[^a-z0-9]+', '-', title.lower()).strip('-')

def unique(slug, taken):
    n, candidate = 2, slug
    while candidate in taken:
        candidate, n = f'{slug}-{n}', n + 1
    taken.add(candidate)
    return candidate

