def compare(old_entries, new_pages):
    old = {e['page_id']: e for e in old_entries}
    added = [p for p in new_pages if p.id not in old]
    changed = [p for p in new_pages if p.id in old and p.version != old[p.id]['version']]
    removed = set(old) - {p.id for p in new_pages}
    return added, changed, removed

